// DUEL 24 — deterministic, serialisable duel engine.
// Pure actions: every exported action clones the incoming state and returns
// { state, events }. The UI animates the events, then adopts the new state.

import { CARD_TYPES } from './cards.js';

export const COLS = 4;
export const ROWS = 3;
export const ZONES_PER_SIDE = COLS * ROWS; // 12
export const TOTAL_ZONES = ZONES_PER_SIDE * 2; // 24
export const FRONT_ROW = ROWS - 1; // row 2 is the attacking row
export const START_LP = 3000;
export const MAX_ENERGY = 10;
export const HAND_LIMIT = 8;
export const FATIGUE_BASE = 150;
export const MAX_LOG = 80;

export class GameError extends Error {
  constructor(message) {
    super(message);
    this.name = 'GameError';
  }
}

export const otherSide = side => (side === 'player' ? 'enemy' : 'player');
export const rowOf = zone => Math.floor(zone / COLS);
export const colOf = zone => zone % COLS;
export const zoneIndex = (row, col) => row * COLS + col;
export const isFront = zone => rowOf(zone) === FRONT_ROW;
export const rowName = row => ['後衛', '中衛', '前衛'][row] ?? '—';
export const colName = col => 'ABCD'[col] ?? '?';
export const zoneName = zone => `${rowName(rowOf(zone))} ${colName(colOf(zone))}`;
export const zoneNumber = (side, zone) => {
  if (side === 'enemy') return zone + 1; // 01–12, back to front
  return TOTAL_ZONES - zone; // 24–13, back to front
};

function cloneState(state) {
  return structuredClone(state);
}

function nextRandom(state) {
  let t = state.rngState >>> 0;
  t = (t + 0x6d2b79f5) >>> 0;
  let r = Math.imul(t ^ (t >>> 15), 1 | t);
  r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
  state.rngState = t;
  return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
}

function shuffled(state, values) {
  const out = values.slice();
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(nextRandom(state) * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

function makeCard(state, type) {
  return {
    uid: state.nextUid++,
    typeId: type.id,
    name: type.name,
    en: type.en,
    cost: type.cost,
    atk: type.atk,
    hp: type.hp,
    maxHp: type.hp,
    rarity: type.rarity,
    element: type.element,
    art: type.art,
    ability: type.ability ? { ...type.ability } : null,
    text: type.text,
  };
}

function buildDeck(state) {
  const cards = [];
  for (const type of CARD_TYPES) {
    cards.push(makeCard(state, type));
    cards.push(makeCard(state, type));
  }
  return shuffled(state, cards);
}

function log(state, text, kind = 'info') {
  state.log.push({
    id: state.log.length ? state.log[state.log.length - 1].id + 1 : 1,
    turn: state.turnNumber,
    text,
    kind,
  });
  if (state.log.length > MAX_LOG) state.log.splice(0, state.log.length - MAX_LOG);
}

function emit(state, event) {
  state.events.push(event);
  return event;
}

function checkWin(state) {
  if (state.phase === 'over') return state.winner;
  const p = state.sides.player.lp;
  const e = state.sides.enemy.lp;
  if (p <= 0 || e <= 0) {
    state.phase = 'over';
    state.winner = p <= 0 && e <= 0 ? 'draw' : p <= 0 ? 'enemy' : 'player';
    emit(state, { type: 'gameover', winner: state.winner });
    log(state, state.winner === 'draw' ? '両者LPゼロ — DRAW' : `${state.sides[state.winner].name} の勝利 — LP ZERO`, 'finish');
  }
  return state.winner;
}

function drawCards(state, side, count) {
  const s = state.sides[side];
  const drawn = [];
  for (let i = 0; i < count; i += 1) {
    if (!s.deck.length) {
      s.fatigue += 1;
      const amount = FATIGUE_BASE * s.fatigue;
      s.lp = Math.max(0, s.lp - amount);
      emit(state, { type: 'fatigue', side, amount, lpAfter: s.lp });
      log(state, `${s.name} はデッキ切れ — ${amount} ダメージ`, 'danger');
      checkWin(state);
      continue;
    }
    const card = s.deck.shift();
    if (s.hand.length >= HAND_LIMIT) {
      emit(state, { type: 'burn', side, card });
      log(state, `${s.name} の手札が限界 — ${card.name} は消滅`, 'danger');
      continue;
    }
    s.hand.push(card);
    drawn.push(card);
    emit(state, { type: 'draw', side, card });
  }
  return drawn;
}

function beginTurn(state, side, { initial = false } = {}) {
  const s = state.sides[side];
  state.turn = side;
  if (!initial) state.turnNumber += 1;
  s.maxEnergy = Math.min(MAX_ENERGY, s.maxEnergy + 1);
  s.energy = s.maxEnergy;
  for (const card of s.field) {
    if (!card) continue;
    card.hasAttacked = false;
    card.hasMoved = false;
    card.justPlayed = false;
  }
  emit(state, { type: 'turn', side, turnNumber: state.turnNumber });
  drawCards(state, side, 1);
  log(state, `${s.name} のターン — ENERGY ${s.energy}/${s.maxEnergy}`, 'turn');
}

export function createGame({
  seed = Date.now(),
  playerName = 'YOU',
  enemyName = 'KAI',
  playerRank = 'SILVER III',
  enemyRank = 'GOLD II',
  first = 'player',
} = {}) {
  const state = {
    seed: seed >>> 0,
    rngState: seed >>> 0,
    nextUid: 1,
    turn: first,
    turnNumber: 1,
    phase: 'playing',
    winner: null,
    events: [],
    log: [],
    sides: {},
  };

  for (const side of ['player', 'enemy']) {
    state.sides[side] = {
      id: side,
      name: side === 'player' ? playerName : enemyName,
      rank: side === 'player' ? playerRank : enemyRank,
      lp: START_LP,
      maxLp: START_LP,
      energy: 0,
      maxEnergy: 2,
      hand: [],
      deck: buildDeck(state),
      field: Array(ZONES_PER_SIDE).fill(null),
      fatigue: 0,
      stats: { dealt: 0, taken: 0, kills: 0, cardsPlayed: 0, attacks: 0 },
    };
  }

  for (const side of ['player', 'enemy']) drawCards(state, side, 4);
  beginTurn(state, first, { initial: true });
  log(state, `DUEL START — ${state.sides[first].name} が先攻 / 24 ZONES / LP ${START_LP}`, 'system');
  state.events = [];
  return state;
}

export function assertTurn(state, side) {
  if (state.phase !== 'playing') throw new GameError('デュエルは終了しています');
  if (state.turn !== side) throw new GameError(side === 'player' ? '相手のターンです' : '自分のターンではありません');
}

export function frontmostTarget(field, col) {
  for (let row = FRONT_ROW; row >= 0; row -= 1) {
    const zone = zoneIndex(row, col);
    if (field[zone]) return zone;
  }
  return null;
}

export function attackInfo(state, side, fromZone) {
  const s = state.sides[side];
  const foe = state.sides[otherSide(side)];
  const card = s.field[fromZone];
  if (!card) return null;
  if (!isFront(fromZone)) return null;
  const targetZone = frontmostTarget(foe.field, colOf(fromZone));
  return {
    card,
    targetZone,
    direct: targetZone === null,
    target: targetZone === null ? null : foe.field[targetZone],
    lpDamage: targetZone === null ? card.atk : 0,
    canAttack: !card.hasAttacked,
  };
}

export function moveTargets(state, side, fromZone) {
  const s = state.sides[side];
  const card = s.field[fromZone];
  if (!card || card.hasMoved || card.hasAttacked) return [];
  const row = rowOf(fromZone);
  const col = colOf(fromZone);
  const out = [];
  for (const nextRow of [row - 1, row + 1]) {
    if (nextRow < 0 || nextRow >= ROWS) continue;
    const zone = zoneIndex(nextRow, col);
    if (!s.field[zone]) out.push(zone);
  }
  return out;
}

export function playableZones(state, side) {
  const field = state.sides[side].field;
  return field.map((card, zone) => (card ? null : zone)).filter(zone => zone !== null);
}

function damageCard(state, side, zone, amount, meta = {}) {
  const s = state.sides[side];
  const card = s.field[zone];
  if (!card) return { destroyed: false, overkill: 0, card: null };
  card.hp -= amount;
  const destroyed = card.hp <= 0;
  const overkill = destroyed ? Math.max(0, -card.hp) : 0;
  emit(state, {
    type: 'damage',
    side,
    zone,
    card,
    amount,
    hpAfter: Math.max(0, card.hp),
    destroyed,
    sourceSide: meta.sourceSide ?? null,
    sourceZone: meta.sourceZone ?? null,
  });
  if (destroyed) {
    s.field[zone] = null;
    emit(state, { type: 'destroy', side, zone, card });
    log(state, `${card.name} は破壊された`, 'danger');
  }
  return { destroyed, overkill, card };
}

function applyOnPlay(state, side, zone, card) {
  const ability = card.ability;
  if (!ability) return;
  const s = state.sides[side];
  const foe = state.sides[otherSide(side)];

  if (ability.type === 'strike') {
    const col = colOf(zone);
    const targetZone = frontmostTarget(foe.field, col);
    if (targetZone === null) {
      foe.lp = Math.max(0, foe.lp - ability.value);
      emit(state, {
        type: 'strike',
        side,
        zone,
        targetZone: null,
        damage: ability.value,
        lpDamage: ability.value,
        lpAfter: foe.lp,
      });
      log(state, `${card.name} の追撃 — 相手LPに ${ability.value} ダメージ`, 'damage');
    } else {
      const target = foe.field[targetZone];
      emit(state, {
        type: 'strike',
        side,
        zone,
        targetZone,
        damage: ability.value,
        target,
        lpDamage: 0,
        lpAfter: foe.lp,
      });
      log(state, `${card.name} の追撃 — ${target.name} に ${ability.value} ダメージ`, 'damage');
      damageCard(state, otherSide(side), targetZone, ability.value, { sourceSide: side, sourceZone: zone });
    }
  }

  if (ability.type === 'heal') {
    const before = s.lp;
    s.lp = Math.min(s.maxLp, s.lp + ability.value);
    const amount = s.lp - before;
    emit(state, { type: 'heal', side, amount, lpAfter: s.lp, zone, card });
    log(state, `${card.name} — LPを ${amount} 回復`, 'heal');
  }

  if (ability.type === 'rally') {
    const row = rowOf(zone);
    let affected = 0;
    for (let col = 0; col < COLS; col += 1) {
      const allyZone = zoneIndex(row, col);
      const ally = s.field[allyZone];
      if (!ally || ally.uid === card.uid) continue;
      ally.atk += ability.value;
      affected += 1;
      emit(state, {
        type: 'buff',
        side,
        zone: allyZone,
        card: ally,
        amount: ability.value,
        atkAfter: ally.atk,
      });
    }
    log(state, `${card.name} の号令 — 同列の味方 ${affected} 体に ATK+${ability.value}`, 'buff');
  }

  checkWin(state);
}

export function playCard(game, side, handUid, zone) {
  const state = cloneState(game);
  state.events = [];
  assertTurn(state, side);
  const s = state.sides[side];
  const index = s.hand.findIndex(card => card.uid === handUid);
  if (index < 0) throw new GameError('そのカードは手札にありません');
  const card = s.hand[index];
  if (!Number.isInteger(zone) || zone < 0 || zone >= ZONES_PER_SIDE) throw new GameError('ゾーンが不正です');
  if (s.field[zone]) throw new GameError('そのゾーンは埋まっています');
  if (card.cost > s.energy) throw new GameError(`ENERGY が足りません（必要 ${card.cost}）`);

  s.energy -= card.cost;
  s.hand.splice(index, 1);
  s.stats.cardsPlayed += 1;
  const instance = {
    ...card,
    hasAttacked: false,
    hasMoved: false,
    justPlayed: true,
  };
  s.field[zone] = instance;
  emit(state, { type: 'summon', side, zone, card: instance });
  log(state, `${s.name} — ${card.name} を ${zoneName(zone)} に召喚`, 'summon');
  applyOnPlay(state, side, zone, instance);
  checkWin(state);
  return { state, events: state.events };
}

export function moveCard(game, side, from, to) {
  const state = cloneState(game);
  state.events = [];
  assertTurn(state, side);
  const s = state.sides[side];
  const card = s.field[from];
  if (!card) throw new GameError('そのゾーンにカードがありません');
  if (card.hasAttacked) throw new GameError('攻撃したカードは移動できません');
  if (card.hasMoved) throw new GameError('このカードはこのターンすでに移動しました');
  if (from === to) throw new GameError('同じゾーンには移動できません');
  if (colOf(from) !== colOf(to)) throw new GameError('同じ列の隣接ゾーンにのみ移動できます');
  if (Math.abs(rowOf(from) - rowOf(to)) !== 1) throw new GameError('前後に1マスだけ移動できます');
  if (s.field[to]) throw new GameError('移動先のゾーンは埋まっています');

  s.field[from] = null;
  s.field[to] = card;
  card.hasMoved = true;
  emit(state, { type: 'move', side, from, to, card });
  log(state, `${s.name} — ${card.name} が ${zoneName(from)} → ${zoneName(to)} へ移動`, 'move');
  return { state, events: state.events };
}

export function attack(game, side, fromZone) {
  const state = cloneState(game);
  state.events = [];
  assertTurn(state, side);
  const s = state.sides[side];
  const foeSide = otherSide(side);
  const foe = state.sides[foeSide];
  const card = s.field[fromZone];
  if (!card) throw new GameError('そのゾーンにカードがありません');
  if (!isFront(fromZone)) throw new GameError('攻撃できるのは前衛のカードだけです');
  if (card.hasAttacked) throw new GameError('このカードはこのターンすでに攻撃しました');

  const col = colOf(fromZone);
  const targetZone = frontmostTarget(foe.field, col);
  const target = targetZone === null ? null : foe.field[targetZone];
  card.hasAttacked = true;
  s.stats.attacks += 1;

  const attackEvent = emit(state, {
    type: 'attack',
    side,
    from: fromZone,
    targetZone,
    target,
    card,
    damage: card.atk,
    overkill: 0,
    lpDamage: 0,
    lpAfter: foe.lp,
  });

  if (targetZone === null) {
    const damage = card.atk;
    foe.lp = Math.max(0, foe.lp - damage);
    s.stats.dealt += damage;
    foe.stats.taken += damage;
    attackEvent.lpDamage = damage;
    attackEvent.lpAfter = foe.lp;
    emit(state, {
      type: 'direct',
      side,
      from: fromZone,
      damage,
      lpAfter: foe.lp,
      card,
    });
    log(state, `${card.name} が直接攻撃 — 相手LPに ${damage} ダメージ`, 'damage');
  } else {
    const result = damageCard(state, foeSide, targetZone, card.atk, { sourceSide: side, sourceZone: fromZone });
    s.stats.dealt += Math.min(card.atk, card.atk - result.overkill);
    foe.stats.taken += Math.min(card.atk, card.atk - result.overkill);
    if (result.destroyed) {
      s.stats.kills += 1;
      if (result.overkill > 0) {
        foe.lp = Math.max(0, foe.lp - result.overkill);
        s.stats.dealt += result.overkill;
        foe.stats.taken += result.overkill;
        attackEvent.overkill = result.overkill;
        attackEvent.lpDamage = result.overkill;
        attackEvent.lpAfter = foe.lp;
        emit(state, {
          type: 'breakthrough',
          side,
          from: fromZone,
          amount: result.overkill,
          lpAfter: foe.lp,
        });
        log(state, `突破 — 余剰 ${result.overkill} ダメージが相手LPへ`, 'damage');
      }
    }
    log(state, `${card.name} が ${target.name} を攻撃 — ${card.atk} ダメージ`, 'damage');
  }

  checkWin(state);
  return { state, events: state.events };
}

export function endTurn(game, side) {
  const state = cloneState(game);
  state.events = [];
  assertTurn(state, side);
  const next = otherSide(side);
  beginTurn(state, next);
  checkWin(state);
  return { state, events: state.events };
}

export function applyAction(game, action) {
  switch (action.type) {
    case 'play':
      return playCard(game, action.side, action.handUid, action.zone);
    case 'move':
      return moveCard(game, action.side, action.from, action.to);
    case 'attack':
      return attack(game, action.side, action.from);
    case 'end':
      return endTurn(game, action.side);
    default:
      throw new GameError(`未知のアクション: ${action.type}`);
  }
}

function emptyZones(field) {
  const out = [];
  for (let zone = 0; zone < ZONES_PER_SIDE; zone += 1) if (!field[zone]) out.push(zone);
  return out;
}

function chooseAiZone(state, side, card, zones) {
  const foe = state.sides[otherSide(side)];
  const scored = zones.map(zone => {
    const row = rowOf(zone);
    const col = colOf(zone);
    let score = 0;
    if (row === FRONT_ROW) score += 120;
    else if (row === 1) score += 55;
    if (foe.field[zoneIndex(FRONT_ROW, col)]) score += 22;
    if (card.hp >= 800 && row === FRONT_ROW) score += 26;
    if (card.atk >= 500 && row === 0) score += 12;
    if (card.ability?.type === 'heal' && row !== FRONT_ROW) score += 18;
    if (card.ability?.type === 'rally' && row !== FRONT_ROW) score += 10;
    return { zone, score };
  });
  scored.sort((a, b) => b.score - a.score);
  return scored[0].zone;
}

function chooseAiAction(state, side) {
  const s = state.sides[side];
  const foe = state.sides[otherSide(side)];

  // 1. Develop the board with the strongest affordable card.
  const affordable = s.hand
    .filter(card => card.cost <= s.energy)
    .sort((a, b) => (b.cost - a.cost) || (b.atk + b.hp) - (a.atk + a.hp));
  const zones = emptyZones(s.field);
  if (affordable.length && zones.length) {
    const card = affordable[0];
    return { type: 'play', side, handUid: card.uid, zone: chooseAiZone(state, side, card, zones) };
  }

  // 2. Push reserves toward the front line.
  const moves = [];
  for (let zone = 0; zone < ZONES_PER_SIDE; zone += 1) {
    const card = s.field[zone];
    if (!card || card.hasMoved || card.hasAttacked || isFront(zone)) continue;
    const forward = zone + COLS;
    if (forward < ZONES_PER_SIDE && !s.field[forward]) {
      moves.push({ from: zone, to: forward, card });
    }
  }
  if (moves.length) {
    moves.sort((a, b) => b.card.atk - a.card.atk);
    return { type: 'move', side, from: moves[0].from, to: moves[0].to };
  }

  // 3. Attack with every ready front-line card, best target first.
  const attackers = [];
  for (let zone = 0; zone < ZONES_PER_SIDE; zone += 1) {
    const card = s.field[zone];
    if (!card || card.hasAttacked || !isFront(zone)) continue;
    const targetZone = frontmostTarget(foe.field, colOf(zone));
    const target = targetZone === null ? null : foe.field[targetZone];
    let priority = 0;
    if (targetZone === null) priority = 100000 + card.atk;
    else if (target && target.hp <= card.atk) priority = 50000 + card.atk;
    else priority = card.atk;
    attackers.push({ zone, priority });
  }
  if (attackers.length) {
    attackers.sort((a, b) => b.priority - a.priority);
    return { type: 'attack', side, from: attackers[0].zone };
  }

  return null;
}

export function aiTurn(game, side = 'enemy') {
  let state = game;
  const steps = [];
  let guard = 0;
  while (state.phase === 'playing' && state.turn === side && guard < 48) {
    guard += 1;
    const action = chooseAiAction(state, side);
    if (!action) break;
    const before = state;
    const result = applyAction(before, action);
    steps.push({ action, before, result });
    state = result.state;
    if (state.phase === 'over') break;
  }
  if (state.phase === 'playing' && state.turn === side) {
    const action = { type: 'end', side };
    const before = state;
    const result = endTurn(before, side);
    steps.push({ action, before, result });
    state = result.state;
  }
  return { state, steps };
}

export function simulate(seed = 1) {
  let state = createGame({ seed });
  let turns = 0;
  while (state.phase === 'playing' && turns < 80) {
    turns += 1;
    const side = state.turn;
    if (side === 'player') {
      // Use the same heuristic for both sides in simulation.
      const { state: next, steps } = aiTurn(state, 'player');
      if (!steps.length) break;
      state = next;
    } else {
      const { state: next, steps } = aiTurn(state, 'enemy');
      if (!steps.length) break;
      state = next;
    }
  }
  return { state, turns };
}

