// Tiny WebAudio synth. No files, no autoplay: every sound follows a gesture.

let ctx = null;
let master = null;
let noiseBuffer = null;
let enabled = true;

function ensure() {
  if (!enabled) return null;
  if (ctx) return ctx;
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return null;
  ctx = new AC();
  master = ctx.createGain();
  master.gain.value = 0.22;
  master.connect(ctx.destination);
  const length = Math.floor(ctx.sampleRate * 0.35);
  noiseBuffer = ctx.createBuffer(1, length, ctx.sampleRate);
  const data = noiseBuffer.getChannelData(0);
  for (let i = 0; i < length; i += 1) data[i] = Math.random() * 2 - 1;
  return ctx;
}

function tone({ freq = 440, to = null, dur = 0.12, type = 'sine', gain = 0.18, delay = 0, attack = 0.008, release = null }) {
  const c = ensure();
  if (!c) return;
  const t0 = c.currentTime + delay;
  const osc = c.createOscillator();
  const g = c.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, t0);
  if (to) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(gain, t0 + attack);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + (release || dur));
  osc.connect(g).connect(master);
  osc.start(t0);
  osc.stop(t0 + dur + 0.03);
}

function noise({ dur = 0.15, gain = 0.12, delay = 0, freq = 1200, q = 0.8, type = 'bandpass' }) {
  const c = ensure();
  if (!c) return;
  const t0 = c.currentTime + delay;
  const src = c.createBufferSource();
  src.buffer = noiseBuffer;
  const filter = c.createBiquadFilter();
  filter.type = type;
  filter.frequency.value = freq;
  filter.Q.value = q;
  const g = c.createGain();
  g.gain.setValueAtTime(gain, t0);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  src.connect(filter).connect(g).connect(master);
  src.start(t0);
  src.stop(t0 + dur + 0.02);
}

export const Sound = {
  setEnabled(value) {
    enabled = Boolean(value);
    if (master) master.gain.value = enabled ? 0.22 : 0;
  },
  get enabled() { return enabled; },
  unlock() { const c = ensure(); if (c && c.state === 'suspended') c.resume(); },
  click() { tone({ freq: 620, to: 760, dur: 0.05, type: 'square', gain: 0.05 }); },
  select() { tone({ freq: 880, dur: 0.04, type: 'triangle', gain: 0.06 }); },
  error() { tone({ freq: 150, to: 100, dur: 0.16, type: 'sawtooth', gain: 0.08 }); },
  summon() {
    tone({ freq: 170, to: 520, dur: 0.22, type: 'triangle', gain: 0.11 });
    tone({ freq: 340, to: 1040, dur: 0.18, type: 'sine', gain: 0.05, delay: 0.03 });
    noise({ dur: 0.18, gain: 0.05, freq: 1800 });
  },
  move() { tone({ freq: 420, to: 620, dur: 0.09, type: 'triangle', gain: 0.06 }); },
  attack() {
    noise({ dur: 0.12, gain: 0.11, freq: 2400, q: 1.4 });
    tone({ freq: 220, to: 70, dur: 0.18, type: 'sawtooth', gain: 0.09 });
  },
  hit() {
    noise({ dur: 0.16, gain: 0.14, freq: 600, q: 0.5 });
    tone({ freq: 120, to: 55, dur: 0.14, type: 'square', gain: 0.1 });
  },
  destroy() {
    noise({ dur: 0.32, gain: 0.16, freq: 380, q: 0.4, type: 'lowpass' });
    tone({ freq: 180, to: 45, dur: 0.3, type: 'sawtooth', gain: 0.08 });
  },
  heal() {
    [523, 659, 784].forEach((f, i) => tone({ freq: f, dur: 0.18, type: 'sine', gain: 0.05, delay: i * 0.06 }));
  },
  buff() {
    [392, 523, 659].forEach((f, i) => tone({ freq: f, to: f * 1.08, dur: 0.14, type: 'triangle', gain: 0.045, delay: i * 0.04 }));
  },
  turn() {
    tone({ freq: 330, dur: 0.12, type: 'triangle', gain: 0.06 });
    tone({ freq: 495, dur: 0.16, type: 'triangle', gain: 0.05, delay: 0.08 });
  },
  enemyTurn() {
    tone({ freq: 220, dur: 0.14, type: 'triangle', gain: 0.06 });
    tone({ freq: 165, dur: 0.2, type: 'triangle', gain: 0.05, delay: 0.1 });
  },
  win() {
    [523, 659, 784, 1046, 1318].forEach((f, i) => tone({ freq: f, dur: 0.32, type: 'triangle', gain: 0.075, delay: i * 0.1 }));
    noise({ dur: 0.5, gain: 0.05, freq: 3000, delay: 0.1 });
  },
  lose() {
    [392, 330, 262, 196].forEach((f, i) => tone({ freq: f, to: f * 0.94, dur: 0.35, type: 'sawtooth', gain: 0.05, delay: i * 0.13 }));
  },
  zero() {
    tone({ freq: 880, to: 55, dur: 0.65, type: 'sawtooth', gain: 0.1 });
    noise({ dur: 0.6, gain: 0.09, freq: 900, q: 0.3 });
  },
};

// Lobby data: a persistent profile, the player's always-on room, and a
// believable online room list populated by rival duelists.

const PROFILE_KEY = 'duel24.profile.v1';

export const BOTS = [
  { name: 'KAI', rank: 'GOLD II', avatarClass: 'pink', mode: 'CASUAL', difficulty: 'normal', line: '前衛を制する者が24を制す。' },
  { name: 'SORA', rank: 'DIAMOND IV', avatarClass: '', mode: 'RANKED', difficulty: 'hard', line: '空を斬る剣は、ゼロまで届く。' },
  { name: 'VEX', rank: 'PLATINUM I', avatarClass: 'pink', mode: 'CASUAL', difficulty: 'normal', line: 'ネオンの中では、影がよく見える。' },
  { name: 'MOMO', rank: 'GOLD IV', avatarClass: 'green', mode: 'CASUAL', difficulty: 'easy', line: '初心者歓迎！でも手は抜かないよ。' },
  { name: 'KURO', rank: 'MASTER', avatarClass: 'gold', mode: 'RANKED', difficulty: 'hard', line: '深夜のLPは、ゼロがよく似合う。' },
  { name: 'NOVA', rank: 'SILVER I', avatarClass: '', mode: 'CASUAL', difficulty: 'easy', line: '24ゾーン、全部使って勝つ。' },
  { name: 'GIGA', rank: 'DIAMOND II', avatarClass: 'gold', mode: 'RANKED', difficulty: 'hard', line: '鋼の前衛は、そう簡単には崩れない。' },
  { name: 'RIN', rank: 'PLATINUM III', avatarClass: 'green', mode: 'RANKED', difficulty: 'normal', line: '風を読めば、突破は見える。' },
];

const ROOM_NAMES = [
  '蒼穹の決闘場',
  'NEON UNDERGROUND',
  '初心者歓迎！24ZONE',
  '深夜のゼロポイント',
  'DUEL ROOM 024',
  'TITAN ARENA',
  '星海のラウンジ',
  'ZERO POINT CAFE',
  '紅蓮のゲート',
];

const CODES = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

export function randomCode(length = 4) {
  let out = '';
  for (let i = 0; i < length; i += 1) out += CODES[Math.floor(Math.random() * CODES.length)];
  return out;
}

export function loadProfile() {
  let stored = null;
  try {
    stored = JSON.parse(localStorage.getItem(PROFILE_KEY) || 'null');
  } catch {
    stored = null;
  }
  const base = {
    name: 'YOU',
    rank: 'SILVER III',
    level: 24,
    wins: 12,
    losses: 7,
    sound: true,
    roomCode: randomCode(),
    createdAt: Date.now(),
  };
  return { ...base, ...(stored || {}) };
}

export function saveProfile(profile) {
  try {
    localStorage.setItem(PROFILE_KEY, JSON.stringify(profile));
  } catch {
    // Storage can be unavailable in private modes; the duel still works.
  }
}

export function pickBot(seed = Math.random()) {
  return BOTS[Math.floor(seed * BOTS.length) % BOTS.length];
}

export function createOwnRoom(profile, bot = pickBot()) {
  return {
    id: `own-${profile.roomCode || randomCode()}`,
    code: profile.roomCode || randomCode(),
    name: '自分のルーム',
    host: profile.name,
    hostRank: profile.rank,
    hostInitial: (profile.name[0] || 'Y').toUpperCase(),
    avatarClass: 'own',
    mode: 'CASUAL',
    ping: 6 + Math.floor(Math.random() * 9),
    status: 'dueling',
    players: 2,
    maxPlayers: 2,
    zones: 24,
    lp: 3000,
    isOwn: true,
    opponent: bot,
    live: true,
  };
}

export function createRivalRooms(profile, ownRoom) {
  const bots = BOTS.slice();
  // Rotate the roster so the room list has a fresh cast each boot.
  const offset = Math.floor(Math.random() * bots.length);
  const rotated = bots.slice(offset).concat(bots.slice(0, offset));
  const rooms = [];
  for (let i = 0; i < 7; i += 1) {
    const bot = rotated[i % rotated.length];
    const dueling = i % 3 !== 1;
    rooms.push({
      id: `rival-${i}-${randomCode(3)}`,
      code: randomCode(4),
      name: ROOM_NAMES[(i + offset) % ROOM_NAMES.length],
      host: bot.name,
      hostRank: bot.rank,
      hostInitial: bot.name[0],
      avatarClass: bot.avatarClass,
      mode: bot.mode,
      ping: 9 + Math.floor(Math.random() * 78),
      status: dueling ? 'dueling' : 'waiting',
      players: dueling ? 2 : 1,
      maxPlayers: 2,
      zones: 24,
      lp: 3000,
      isOwn: false,
      opponent: bot,
      live: i < 2,
    });
  }
  return [ownRoom, ...rooms];
}

export function refreshRooms(rooms) {
  return rooms.map(room => {
    if (room.isOwn) {
      return {
        ...room,
        ping: Math.max(4, room.ping + Math.floor(Math.random() * 5) - 2),
      };
    }
    const ping = Math.max(7, Math.min(120, room.ping + Math.floor(Math.random() * 13) - 6));
    let status = room.status;
    let players = room.players;
    if (!room.isOwn && Math.random() < 0.16) {
      if (status === 'waiting') {
        status = 'dueling';
        players = 2;
      } else {
        status = 'waiting';
        players = 1;
      }
    }
    return { ...room, ping, status, players };
  });
}

export function roomStatusLabel(room, currentId) {
  if (room.id === currentId) return { text: '参加中', className: 'dueling' };
  if (room.isOwn) return { text: '自分のルーム', className: 'full' };
  if (room.status === 'dueling' || room.players >= 2) return { text: '対戦中', className: 'dueling' };
  return { text: '待機中', className: 'waiting' };
}

export function rankForName(name) {
  return BOTS.find(bot => bot.name === name)?.rank || 'GOLD II';
}

