content.text:
Now the main app.js. This is big. Let's carefully implement.

Imports:
```js
import { createGame, playCard, moveCard, attack, endTurn, applyAction, aiTurn, playableZones, moveTargets, attackInfo, isFront, rowOf, colOf, zoneName, zoneNumber, TOTAL_ZONES, START_LP, MAX_ENERGY, GameError } from './engine.js';
import { CARD_TYPES, ELEMENTS } from './cards.js';
import { cardArt, avatarGlyph } from './art.js';
import { Sound } from './audio.js';
import { loadProfile, saveProfile, createOwnRoom, createRivalRooms, refreshRooms, pickBot } from './lobby.js';
```

DOM refs helper:
```js
const $ = sel => document.querySelector(sel);
```

State:
```js
const S = {
  profile: null,
  rooms: [],
  currentRoomId: null,
  ownRoomId: null,
  game: null,
  ui: {
    selectedHand: null,
    selectedZone: null,
    busy: false,
    filter: 'all',
    search: '',
    logOpen: false,
    sidebarOpen: false,
    muted: false,
    lastHand: new Set(),
    resultShown: false,
    introShown: false,
    roomRenderKey: '',
  },
  timers: new Set(),
};
```

Utilities:
```js
const sleep = ms => new Promise(res => { const id = setTimeout(()=>{S.timers.delete(id); res();}, ms); S.timers.add(id); });
const el = (html) => { ... } // no
function escapeHtml(str) {...}
```
Need escaping for room names/profile (user-controlled localStorage). Use a helper.

Init:
```js
function init() {
  S.profile = loadProfile();
  S.ui.muted = !S.profile.sound;
  Sound.setEnabled(S.profile.sound);
  const bot = pickBot();
  const own = createOwnRoom(S.profile, bot);
  S.ownRoomId = own.id;
  S.rooms = createRivalRooms(S.profile, own);
  S.currentRoomId = own.id;
  S.game = createGame({ seed: Date.now(), playerName: S.profile.name, enemyName: own.opponent.name, playerRank: S.profile.rank, enemyRank: own.opponent.rank });
  buildHud('enemy'); buildHud('player');
  renderAll();
  bindEvents();
  startStars();
  // intro
  showToast('ROOM CREATED', `自分のルーム #${own.code} を生成し、自動参加しました。`, 'ok', 4200);
  setTimeout(() => { showToast('MATCH FOUND', `${own.opponent.name} がルームに参加。LP 3000 / 24 ZONES。`, 'ok', 3800); }, 900);
  setTimeout(() => { showBanner('DUEL START', '', 900); Sound.turn(); }, 500);
  // animate initial deal? hand rendered already; maybe deal animation.
  requestAnimationFrame(() => dealInitialHand());
}
```
Wait, `bindEvents` should be before render? Render uses event delegation, so okay. `startStars` after DOM.

`dealInitialHand` could add `.is-new` to hand cards. We can handle in renderHand: first render all new; CSS animation. No need extra.

`buildHud(side)`:
```js
function buildHud(side) {
  const root = document.getElementById(side==='enemy'?'enemy-hud':'player-hud');
  const g = S.game.sides[side];
  const isEnemy = side==='enemy';
  root.innerHTML = `
    <div class="avatar">${escapeHtml(avatarGlyph(g.name))}<span class="lv">${isEnemy ? 'AI' : 'LV '+S.profile.level}</span></div>
    <div class="hud-main">
      <div class="hud-top">
        <span class="hud-name">${escapeHtml(g.name)}</span>
        <span class="hud-rank">${escapeHtml(g.rank)}</span>
        <span class="hud-tag">DECK <b data-deck>${g.deck.length}</b> / HAND <b data-hand>${g.hand.length}</b></span>
      </div>
      <div class="lp-row">
        <span class="lp-label">LP</span>
        <div class="lp-bar" id="${side}-lp-bar"><i class="lp-fill" id="${side}-lp-fill"></i></div>
        <span class="lp-num" id="${side}-lp-num">${g.lp}<small>/${g.maxLp}</small></span>
      </div>
    </div>
    <div class="hud-right">
      <div class="hand-badge"><b data-hand-badge>${g.hand.length}</b><span>HAND</span></div>
