```js
async function animateTransition(oldState, result, action) {
  const events = result.events || [];
  const primary = events[0];
  if (action.type === 'play') {
    const summon = events.find(e => e.type === 'summon');
    await animateSummon(summon);
    for (const ev of events) {
      if (ev === summon) continue;
      if (ev.type === 'strike') await animateStrike(ev);
      else if (ev.type === 'heal') animateHeal(ev);
      else if (ev.type === 'buff') animateBuff(ev);
      else if (ev.type === 'damage' && !events.some(e=>e.type==='strike' && e.targetZone===ev.zone)) animateDamage(ev);
      else if (ev.type === 'destroy' && !events.some(e=>e.type==='strike' && e.targetZone===ev.zone)) animateDestroy(ev);
    }
  } else if (action.type === 'move') { ... }
  else if (action.type === 'attack') { await animateAttack(events.find(e=>e.type==='attack')); }
  else if (action.type === 'end') { const turn = events.find(e=>e.type==='turn'); showTurnBanner(turn.side); await sleep(350); }
  else await sleep(120);
  // gameover banner handled later
}
