      const handCard = S.game.sides.player.hand.find(c=>c.uid===handUid);
      if (!handCard) return;
      if (handCard.cost > S.game.sides.player.energy) { toast...; return; }
      performAction({type:'play', side:'player', handUid, zone});
      return;
    }
    if (S.ui.selectedZone != null) {
      if (zone === S.ui.selectedZone) { deselect; return; }
      const moves = moveTargets(S.game,'player',S.ui.selectedZone);
      if (moves.includes(zone)) { performAction({type:'move',...}); return; }
      if (card) { select zone; return; }
      return;
    }
    if (card) { select zone; Sound.select(); render...; }
    return;
