```js
async function animateAttack(ev) {
  const side = ev.side;
  const targetSide = side==='player'?'enemy':'player';
  const attackerEl = getCardEl(side, ev.from);
  const targetEl = ev.targetZone != null ? getCardEl(targetSide, ev.targetZone) : null;
  const targetHud = document.getElementById(`${targetSide}-hud`);
  const targetRect = targetEl ? rectOf(targetEl) : rectOf(targetHud);
  if (attackerEl && targetRect) {
    const ar = rectOf(attackerEl);
    const dx = (targetRect.left + targetRect.width/2) - (ar.left + ar.width/2);
    const dy = (targetRect.top + targetRect.height/2) - (ar.top + ar.height/2);
    const anim = attackerEl.animate([
      { transform: 'translate(0,0) scale(1)' },
      { transform: `translate(${dx*0.22}px, ${dy*0.22}px) scale(1.06)`, offset: 0.42 },
      { transform: 'translate(0,0) scale(1)' }
    ], { duration: 320, easing: 'cubic-bezier(.2,.8,.2,1)' });
    Sound.attack();
    await sleep(150);
    slashAt(targetRect, Math.atan2(dy, dx) * 180/Math.PI);
    spawnSparks(targetRect, 12, side==='player'?'pink':'cyan');
    await anim.finished.catch(()=>{});
  } else {
    Sound.attack();
  }
  const dmg = ev.damage;
  damagePop(targetRect, `-${dmg}`, ev.targetZone==null?'lp':'');
  if (ev.lpDamage > 0) {
    setTimeout(()=>damagePop(rectOf(targetHud), `LP -${ev.lpDamage}`, 'lp'), 100);
    targetHud.querySelector('.lp-bar')?.classList.add('hit');
    setTimeout(()=>targetHud.querySelector('.lp-bar')?.classList.remove('hit'), 400);
  }
  if (ev.target && ev.overkill > 0) { ... breakthrough pop }
  if (targetEl && ev.target && ev.target.hp - ev.damage <= 0) {
    shatter(targetEl);
    Sound.destroy();
