  return `<div class="field-card rarity-${card.rarity}"
      data-uid="${card.uid}"
      style="--rarity:${rarity};--element:${el.color};--element-soft:${hexA(el.color, 0.17)};--element-glow:${hexA(el.color, 0.3)};--float-delay:${floatDelay};--sheen-delay:${sheenDelay}"
