        style="--rot:${rotation}deg;--lift:${lift}px;--z:${index};--deal-delay:${index * 0.045}s;--rarity:${rarity};--element:${el.color};--element-soft:${hexA(el.color, 0.19)};--element-glow:${hexA(el.color, 0.3)}"
