    spark.style.top = `${rect.top + rect.height / 2}px`;
    spark.style.setProperty('--dx', `${(Math.random() - 0.5) * 110}px`);
    spark.style.setProperty('--dy', `${(Math.random() - 0.5) * 110}px`);
    document.body.appendChild(spark);
    setTimeout(() => spark.remove(), 560);
  }
