function selectHand(uid) {
  if (!canAct()) return;
  if (S.ui.selectedHand === uid) {
    S.ui.selectedHand = null;
  } else {
    S.ui.selectedHand = uid;
    S.ui.selectedZone = null;
    Sound.select();
    const card = S.game.sides.player.hand.find(item => item.uid === uid);
    if (card && card.cost > S.game.sides.player.energy) {
      showToast('ENERGY不足', `${card.name} には ENERGY ${card.cost} が必要です。`, 'warn', 2400);
    }
  }
  renderBoard();
  renderHand();
  renderControls();
}

function selectZone(zone) {
  if (!canAct()) return;
  if (S.ui.selectedZone === zone) {
    S.ui.selectedZone = null;
    S.ui.selectedHand = null;
  } else {
    S.ui.selectedZone = zone;
    S.ui.selectedHand = null;
    Sound.select();
  }
  renderBoard();
  renderHand();
  renderControls();
}

function handleHandClick(uid) {
  selectHand(uid);
}

function handleZoneClick(side, zone) {
  if (!S.game || !canAct()) return;
  const player = S.game.sides.player;

  if (side === 'enemy') {
    const info = selectedAttackInfo();
    if (info && !info.card.hasAttacked && info.targetZone === zone) {
      performAction({ type: 'attack', side: 'player', from: S.ui.selectedZone });
      return;
    }
    const card = S.game.sides.enemy.field[zone];
    if (card) showToast('ENEMY UNIT', `${card.name} — ATK ${card.atk} / HP ${Math.max(0, card.hp)}`, 'ok', 2200);
    return;
  }

  const ownCard = player.field[zone];

  if (S.ui.selectedHand !== null) {
    if (ownCard) {
      selectZone(zone);
      return;
    }
    const handCard = player.hand.find(card => card.uid === S.ui.selectedHand);
    if (!handCard) return;
    if (handCard.cost > player.energy) {
      showToast('ENERGY不足', `必要 ENERGY ${handCard.cost} / 現在 ${player.energy}`, 'warn', 2200);
      return;
    }
    performAction({ type: 'play', side: 'player', handUid: handCard.uid, zone });
    return;
  }

  if (S.ui.selectedZone !== null) {
    if (zone === S.ui.selectedZone) {
      S.ui.selectedZone = null;
      renderBoard();
      renderControls();
      return;
    }
    if (moveTargets(S.game, 'player', S.ui.selectedZone).includes(zone)) {
      performAction({ type: 'move', side: 'player', from: S.ui.selectedZone, to: zone });
      return;
    }
    if (ownCard) {
      selectZone(zone);
      return;
    }
    return;
  }

  if (ownCard) selectZone(zone);
}

async function performAction(action) {
  if (!S.game || S.ui.busy || S.ui.auto || S.game.phase !== 'playing') return false;
  if (action.side && S.game.turn !== action.side) return false;
  S.ui.busy = true;
  renderControls();
  renderHand();
  try {
    const result = applyAction(S.game, action);
    await animateTransition(S.game, result, action);
    S.game = result.state;
    S.ui.selectedHand = null;
    S.ui.selectedZone = null;
    renderAll();
    if (S.game.phase === 'over') await handleGameOver();
    return true;
  } catch (error) {
    Sound.error();
    showToast('ACTION FAILED', error?.message || 'その操作はできません', 'bad', 2600);
    return false;
  } finally {
    S.ui.busy = false;
    renderControls();
    renderHand();
  }
}

async function endPlayerTurn() {
  if (!isPlayerTurn() || S.ui.busy || S.ui.auto) return;
  const ok = await performAction({ type: 'end', side: 'player' });
  if (ok && S.game.phase === 'playing' && S.game.turn === 'enemy') {
    runEnemyTurn();
  }
}

async function allAttack() {
  if (!isPlayerTurn() || S.ui.busy || S.ui.auto) return;
  S.ui.auto = true;
  renderControls();
  try {
    let guard = 0;
    while (guard < 16) {
      guard += 1;
      const ready = getReadyAttackers();
      if (!ready.length || S.game.phase !== 'playing') break;
      const ok = await performAction({ type: 'attack', side: 'player', from: ready[0] });
      if (!ok) break;
      await sleep(170);
    }
  } finally {
    S.ui.auto = false;
    renderControls();
    renderHand();
  }
}

