export function activateSet(game, side, zone) {
  const state = cloneState(game);
  state.events = [];
  assertTurn(state, side);
  if (state.battlePhase) throw new GameError('バトルフェイズ中は発動できません');
  const s = state.sides[side];
  const card = s.field[zone];
  if (!card) throw new GameError('そのゾーンにカードがありません');
  if (!isSTSlot(zone)) throw new GameError('魔法・罠ゾーンのカードではありません');
  if (!card.faceDown) throw new GameError('セットされたカードではありません');
  if (card.kind === 'trap') throw new GameError('罠カードは相手の攻撃時に自動発動します');
  card.faceDown = false;
  emit(state, { type: 'activate', side, zone, card, kind: 'spell' });
  log(state, `${s.name} — セットした魔法 ${card.name} を発動`, 'summon');
  resolveSpell(state, side, zone, card);
  checkWin(state);
  return { state, events: state.events };
}

export function changePosition(game, side, zone) {
  const state = cloneState(game);
  state.events = [];
  assertTurn(state, side);
  if (state.battlePhase) throw new GameError('表示形式の変更はメインフェイズのみです');
  const s = state.sides[side];
  const card = s.field[zone];
  if (!card || card.kind !== 'monster') throw new GameError('そのゾーンにモンスターがいません');
  if (card.summonedTurn === state.turnNumber) throw new GameError('召喚・セットしたターンは表示形式を変更できません');
  if (card.hasAttacked) throw new GameError('攻撃したモンスターは表示形式を変更できません');

  if (card.faceDown) {
    card.faceDown = false;

  createOwnRoom,
  createRivalRooms,
  createSoloRoom,
  refreshRooms,
  pickBot,
} from './lobby.js';

const $ = selector => document.querySelector(selector);
const $$ = selector => Array.from(document.querySelectorAll(selector));
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

const RARITY = {
  common: '#7d8da3',
  rare: '#3fa9ff',
  epic: '#b06bff',
  legendary: '#ffb84d',
};

const S = {
  profile: null,
  rooms: [],
  ownRoomId: null,
  currentRoomId: null,
  activeRoom: null,
  mode: 'online',
  soloDifficulty: 'normal',
  game: null,
  ui: {
    selectedHand: null,
    selectedZone: null,
    setMode: false,

const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ESCAPES[char]);
const escapeAttr = escapeHtml;

function hexA(hex, alpha) {
  const raw = String(hex || '#7d8da3').replace('#', '');
  const full = raw.length === 3 ? raw.split('').map(c => c + c).join('') : raw;
  const number = parseInt(full, 16);
  if (Number.isNaN(number)) return `rgba(125, 141, 163, ${alpha})`;
  return `rgba(${(number >> 16) & 255}, ${(number >> 8) & 255}, ${number & 255}, ${alpha})`;
}

function elementOf(card) {
  return ELEMENTS[card.element] || ELEMENTS.fire;
}

function abilityShort(card) {
  if (!card.ability) return '';
  if (card.ability.type === 'strike') return `STRIKE ${card.ability.value}`;
  if (card.ability.type === 'heal') return `HEAL ${card.ability.value}`;
  if (card.ability.type === 'rally') return `RALLY +${card.ability.value}`;
  return '';
}

function padZone(number) {
  return String(number).padStart(2, '0');
}

function isPlayerTurn() {
  return Boolean(S.game && S.game.phase === 'playing' && S.game.turn === 'player');
}

function canAct() {
  return isPlayerTurn() && !S.ui.busy && !S.ui.auto;
}

function rectOf(element) {
  return element ? element.getBoundingClientRect() : null;
}

function getZoneEl(side, zone) {
  return document.querySelector(`.zone[data-side="${side}"][data-zone="${zone}"]`);
}

function getCardEl(side, zone) {
  return document.querySelector(`.zone[data-side="${side}"][data-zone="${zone}"] .field-card`);
}

function getHandEl(uid) {
  return document.querySelector(`[data-hand-uid="${uid}"]`);
}

function getReadyAttackers() {
  if (!S.game) return [];
  const field = S.game.sides.player.field;
  return field
    .map((card, zone) => (card && isFront(zone) && !card.hasAttacked ? zone : null))
    .filter(zone => zone !== null);
}

function selectedAttackInfo() {
  if (!canAct() || S.ui.selectedZone === null) return null;
  const card = S.game.sides.player.field[S.ui.selectedZone];
  if (!card || !isFront(S.ui.selectedZone) || card.hasAttacked) return null;
  return attackInfo(S.game, 'player', S.ui.selectedZone);
}

