content.text:
function renderAll() {
  if (!S.game) return;
  if (S.ui.selectedZone !== null && !S.game.sides.player.field[S.ui.selectedZone]) S.ui.selectedZone = null;
  if (S.ui.selectedHand !== null && !S.game.sides.player.hand.some(card => card.uid === S.ui.selectedHand)) S.ui.selectedHand = null;
  updateHud('enemy');
  updateHud('player');
  renderBoard();
  renderHand();
  renderEnergy();
  renderControls();
  renderLog();
  renderMode();
  renderSoloCard();
  renderMyRoom();
  renderRoomList();
  renderProfile();
}

function renderBoard() {
  const board = $('#board');
  const info = selectedAttackInfo();
  const moves = S.ui.selectedZone !== null ? moveTargets(S.game, 'player', S.ui.selectedZone) : [];
  const selectedHand = S.ui.selectedHand !== null
    ? S.game.sides.player.hand.find(card => card.uid === S.ui.selectedHand)
    : null;
  const playable = selectedHand && canAct() && selectedHand.cost <= S.game.sides.player.energy;

  const rows = [];
  for (const row of [0, 1, 2]) rows.push(renderBoardRow('enemy', row, { info, moves, playable }));
  rows.push(`<div class="board-mid"><span>ENEMY FRONT</span><b>DUEL 24</b><span>PLAYER FRONT</span></div>`);
  for (const row of [2, 1, 0]) rows.push(renderBoardRow('player', row, { info, moves, playable }));
  board.innerHTML = rows.join('');
}

function renderBoardRow(side, row, context) {
  const cells = [];
  for (let col = 0; col < 4; col += 1) cells.push(renderZone(side, row * 4 + col, context));
  const label = ['後衛', '中衛', '前衛'][row];
  const english = ['BACK', 'MID', 'FRONT'][row];
  return `<div class="board-row ${side}">
    <div class="row-label"><span>${label}</span><span>${english}</span></div>
    ${cells.join('')}
  </div>`;
}

function renderZone(side, zone, context) {
  const s = S.game.sides[side];
  const card = s.field[zone];
  const classes = ['zone'];
  if (side === 'enemy') classes.push('enemy-side');
  let extra = '';
  let aria = `${side === 'enemy' ? '相手' : '自分'} ${zoneName(zone)}`;

  if (!card) {
    if (side === 'player' && context.playable && canAct()) {
      classes.push('playable');
      extra = '<span class="zone-plus">+</span>';
    }
    if (side === 'player' && canAct() && context.moves.includes(zone)) {
      classes.push('move-target');
      extra = '<span class="zone-plus">↕</span>';
    }
    aria += ' 空きゾーン';
  } else {
    aria += ` ${card.name} ATK ${card.atk} HP ${card.hp}`;
    if (side === 'player' && S.ui.selectedZone === zone) classes.push('selected');
    if (side === 'enemy' && context.info && context.info.targetZone === zone) classes.push('attack-target');
    if (side === 'player' && canAct() && isFront(zone) && !card.hasAttacked) classes.push('ready');
    if (card.hasAttacked) classes.push('exhausted');
    if (side === 'enemy' && context.info && context.info.direct) {
      // Direct attacks target the enemy LP, not an empty zone.
    }
  }

  const content = card ? renderFieldCard(card, side, zone) : extra;
  return `<div class="${classes.join(' ')}" role="button" tabindex="0" data-side="${side}" data-zone="${zone}" aria-label="${escapeAttr(aria)}">
    <span class="zone-no">${padZone(zoneNumber(side, zone))}</span>
    <span class="zone-col">${'ABCD'[colOf(zone)]}</span>
    ${content}
  </div>`;
}

function renderFieldCard(card, side, zone) {
  const el = elementOf(card);
  const rarity = RARITY[card.rarity] || RARITY.common;
  const hpPercent = Math.max(0, Math.min(100, (card.hp / card.maxHp) * 100));
  const hpClass = hpPercent <= 25 ? 'low' : hpPercent <= 55 ? 'mid' : '';
  const floatDelay = `-${((zone * 7) % 11) * 0.31}s`;
  const sheenDelay = `-${((zone * 3) % 7) * 0.7}s`;
  return `<div class="field-card rarity-${card.rarity}"
      data-uid="${card.uid}"
      style="--rarity:${rarity};--element:${el.color};--element-soft:${hexA(el.color, 0.17)};--element-glow:${hexA(el.color, 0.3)};--float-delay:${floatDelay};--sheen-delay:${sheenDelay}"
      title="${escapeAttr(`${card.name} / ${card.text}`)}">
    <span class="fc-cost">${card.cost}</span>
    <div class="fc-name">${escapeHtml(card.name)}</div>
    <div class="fc-el">${el.label}</div>
    <div class="fc-stats"><span class="fc-atk">${card.atk}</span><span class="fc-hp">${Math.max(0, card.hp)}</span></div>
    <div class="fc-hpbar"><i class="${hpClass}" style="width:${hpPercent}%"></i></div>
    ${card.ability ? `<span class="fc-ability" title="${escapeAttr(card.text)}">✦</span>` : ''}
  </div>`;
}

function renderHand() {
  const wrap = $('#hand');
  const hand = S.game.sides.player.hand;
  if (!hand.length) {
    wrap.innerHTML = '<div class="hand-empty">手札なし — ターン開始時に1枚ドロー</div>';
    S.ui.lastHand = new Set();
    return;
  }
  const locked = !isPlayerTurn() || S.ui.busy || S.ui.auto;
  const energy = S.game.sides.player.energy;
  const count = hand.length;
  wrap.innerHTML = hand.map((card, index) => {
    const el = elementOf(card);
    const rarity = RARITY[card.rarity] || RARITY.common;
    const rotation = (index - (count - 1) / 2) * 2.2;
    const lift = Math.abs(index - (count - 1) / 2) * 1.5;
    const isNew = !S.ui.lastHand.has(card.uid);
    const classes = ['hand-card'];
    if (isNew) classes.push('is-new');
    if (S.ui.selectedHand === card.uid) classes.push('selected');
    if (locked || card.cost > energy) classes.push('unaffordable');
    return `<button class="${classes.join(' ')}" data-hand-uid="${card.uid}"
        style="--rot:${rotation}deg;--lift:${lift}px;--z:${index};--deal-delay:${index * 0.045}s;--rarity:${rarity};--element:${el.color};--element-soft:${hexA(el.color, 0.19)};--element-glow:${hexA(el.color, 0.3)}"
        aria-label="${escapeAttr(`${card.name} コスト${card.cost} ATK${card.atk} HP${card.hp}`)}"
        title="${escapeAttr(card.text)}">
      <span class="hc-cost">${card.cost}</span>
      ${card.ability ? `<span class="hc-ability">${escapeHtml(abilityShort(card))}</span>` : ''}
      <div class="hc-body">
        <div class="hc-name">${escapeHtml(card.name)}</div>
        <div class="hc-en">${escapeHtml(card.en)}</div>
      </div>
      <div class="hc-stats"><span class="atk">${card.atk}<small>ATK</small></span><span class="hp">${card.hp}<small>HP</small></span></div>
      <div class="hc-hpbar"><i></i></div>
    </button>`;
  }).join('');
